-- Hosting starts with no accounts; use 02-configure-access.sql.

-- The current dashboard has several evolving CSV-backed operational modules.
-- Keep their UI-shaped records in a constrained dataset store until each
-- workflow has an independently finalized relational contract.
CREATE TABLE ekapon.dashboard_records (
    id           bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
    dataset      text NOT NULL CHECK (dataset IN (
        'owners', 'pets', 'paravets', 'respondents', 'households',
        'animals', 'stubs', 'services', 'programs', 'participants'
    )),
    record_id    text NOT NULL CHECK (length(record_id) BETWEEN 1 AND 100),
    record_data  jsonb NOT NULL CHECK (
        jsonb_typeof(record_data) = 'object'
        AND record_data ? 'id'
        AND record_data->>'id' = record_id
    ),
    archived     boolean NOT NULL DEFAULT false,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (dataset, record_id)
);
CREATE INDEX dashboard_records_listing_idx
    ON ekapon.dashboard_records (dataset, archived, updated_at DESC);
CREATE UNIQUE INDEX dashboard_program_date_unique
    ON ekapon.dashboard_records (lower((record_data->>'barangay')), (record_data->>'date'))
    WHERE dataset = 'programs' AND NOT archived
      AND COALESCE(record_data->>'status', '') <> 'Cancelled';
CREATE TRIGGER dashboard_records_audit
    AFTER INSERT OR UPDATE OR DELETE ON ekapon.dashboard_records
    FOR EACH ROW EXECUTE FUNCTION ekapon.audit_row();

CREATE TABLE ekapon.dashboard_import_batches (
    batch_id      uuid PRIMARY KEY,
    dataset       text NOT NULL CHECK (dataset IN (
        'owners', 'pets', 'paravets', 'respondents', 'households',
        'animals', 'stubs', 'services', 'programs', 'participants'
    )),
    actor_id      bigint NOT NULL REFERENCES ekapon.accounts(id) ON DELETE RESTRICT,
    label         text NOT NULL CHECK (length(label) BETWEEN 1 AND 160),
    created_at    timestamptz NOT NULL DEFAULT now(),
    undone_at     timestamptz
);
CREATE TABLE ekapon.dashboard_import_items (
    batch_id       uuid NOT NULL REFERENCES ekapon.dashboard_import_batches(batch_id) ON DELETE CASCADE,
    record_id      text NOT NULL,
    existed_before boolean NOT NULL,
    before_data    jsonb,
    before_archived boolean,
    after_data     jsonb NOT NULL,
    PRIMARY KEY (batch_id, record_id),
    CHECK ((existed_before AND before_data IS NOT NULL AND before_archived IS NOT NULL)
           OR (NOT existed_before AND before_data IS NULL AND before_archived IS NULL))
);

CREATE TABLE ekapon.prelistings (
    id             bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
    reference      text PRIMARY KEY,
    owner_name     text NOT NULL CHECK (length(btrim(owner_name)) BETWEEN 1 AND 120),
    mobile         text NOT NULL CHECK (mobile ~ '^09[0-9]{2}[- ]?[0-9]{3}[- ]?[0-9]{4}$'),
    barangay_id    integer NOT NULL REFERENCES ekapon.barangays(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
    program        text NOT NULL CHECK (program IN ('Kapon (spay / neuter)', 'Anti-rabies', 'Microchip', 'Lahat / All three')),
    pets           jsonb NOT NULL CHECK (jsonb_typeof(pets) = 'array' AND jsonb_array_length(pets) BETWEEN 1 AND 10),
    submitted_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX prelistings_submitted_idx ON ekapon.prelistings (submitted_at DESC);
CREATE TRIGGER prelistings_audit
    AFTER INSERT OR UPDATE OR DELETE ON ekapon.prelistings
    FOR EACH ROW EXECUTE FUNCTION ekapon.audit_row();

-- Expose only the API contract. In particular, password hashes and the
-- temporary-credential table are not readable by the API login role.
GRANT USAGE ON SCHEMA ekapon TO ekapon_admin;
GRANT USAGE ON TYPE ekapon.account_type, ekapon.account_status TO ekapon_admin;
GRANT SELECT ON ekapon.barangays TO ekapon_admin;
GRANT SELECT (
    id, account_key, username, account_type, first_name, middle_name, last_name, suffix,
    full_name, mobile, barangay_id, paravet_id, owner_id, status, created_at,
    last_login_at, archived_at
) ON ekapon.accounts TO ekapon_admin;
GRANT INSERT (username, account_type, first_name, middle_name, last_name, suffix,
              mobile, barangay_id, paravet_id, owner_id)
    ON ekapon.accounts TO ekapon_admin;
GRANT UPDATE (first_name, middle_name, last_name, suffix, mobile, barangay_id,
              failed_login_count, locked_until)
    ON ekapon.accounts TO ekapon_admin;
GRANT DELETE ON ekapon.accounts TO ekapon_admin;
GRANT USAGE, SELECT ON SEQUENCE ekapon.accounts_id_seq, ekapon.account_key_seq,
    ekapon.barangays_id_seq, ekapon.login_attempts_id_seq TO ekapon_admin;
GRANT SELECT (account_id, used_at, destroyed_at, locked_at, expires_at)
    ON ekapon.temp_credentials TO ekapon_admin;
GRANT SELECT (ip) ON ekapon.login_attempts TO ekapon_admin;
GRANT INSERT (login_identifier, method, success, reason, ip)
    ON ekapon.login_attempts TO ekapon_admin;
GRANT DELETE ON ekapon.login_attempts TO ekapon_admin;
GRANT SELECT ON ekapon.audit_log TO ekapon_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON ekapon.system_settings, ekapon.role_feature_access TO ekapon_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON ekapon.dashboard_records TO ekapon_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON ekapon.dashboard_import_batches,
    ekapon.dashboard_import_items TO ekapon_admin;
GRANT SELECT, INSERT ON ekapon.prelistings TO ekapon_admin;
GRANT USAGE, SELECT ON SEQUENCE ekapon.dashboard_records_id_seq, ekapon.prelistings_id_seq TO ekapon_admin;
GRANT EXECUTE ON FUNCTION ekapon.find_barangay(text),
    ekapon.setting_int(text),
    ekapon.log_activity(text, text),
    ekapon.log_login_attempt(text, bigint, text, boolean, text, inet),
    ekapon.recent_failed_logins(inet, integer),
    ekapon.issue_temp_password(bigint),
    ekapon.verify_temp_password(text, text, inet),
    ekapon.set_permanent_password(bigint, text),
    ekapon.verify_password(text, text, inet),
    ekapon.archive_records(text, bigint[], boolean)
TO ekapon_admin;

REVOKE ALL ON ALL TABLES IN SCHEMA ekapon FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA ekapon FROM PUBLIC;
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA ekapon FROM PUBLIC;

-- SOURCE: db/005_census_submissions.sql
-- Paravet census forms are staged for review and never write directly to the
-- approved dashboard registry.

CREATE TABLE ekapon.census_submissions (
    submission_id uuid PRIMARY KEY,
    actor_id      bigint NOT NULL REFERENCES ekapon.accounts(id) ON DELETE RESTRICT,
    barangay_id   integer NOT NULL REFERENCES ekapon.barangays(id) ON DELETE RESTRICT,
    label         text NOT NULL CHECK (length(btrim(label)) BETWEEN 1 AND 160),
    records       jsonb NOT NULL CHECK (
        jsonb_typeof(records) = 'array'
        AND jsonb_array_length(records) BETWEEN 1 AND 1000
    ),
    status        text NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending', 'approved', 'rejected')),
    reviewed_by   bigint REFERENCES ekapon.accounts(id) ON DELETE RESTRICT,
    reviewed_at   timestamptz,
    review_note   text CHECK (review_note IS NULL OR length(review_note) <= 500),
    created_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT census_submissions_review_state_check CHECK (
        (status = 'pending' AND reviewed_by IS NULL AND reviewed_at IS NULL)
        OR
        (status IN ('approved', 'rejected') AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)
    )
);

CREATE INDEX census_submissions_status_time_idx
    ON ekapon.census_submissions (status, created_at DESC);
CREATE INDEX census_submissions_actor_time_idx
    ON ekapon.census_submissions (actor_id, created_at DESC);

GRANT SELECT, INSERT, UPDATE, DELETE ON ekapon.census_submissions TO ekapon_admin;

-- SOURCE: db/006_census_submitter_retention.sql
-- Preserve census submission attribution without blocking account removal.

ALTER TABLE ekapon.census_submissions
    ADD COLUMN submitter_name text;

UPDATE ekapon.census_submissions s
   SET submitter_name = a.full_name
  FROM ekapon.accounts a
 WHERE a.id = s.actor_id;

ALTER TABLE ekapon.census_submissions
    ALTER COLUMN submitter_name SET NOT NULL,
    ALTER COLUMN actor_id DROP NOT NULL,
    DROP CONSTRAINT census_submissions_actor_id_fkey,
    ADD CONSTRAINT census_submissions_actor_id_fkey
        FOREIGN KEY (actor_id) REFERENCES ekapon.accounts(id) ON DELETE SET NULL;

-- SOURCE: db/008_profile_preferences_undo.sql
CREATE TABLE IF NOT EXISTS ekapon.account_preferences (
    account_id bigint PRIMARY KEY REFERENCES ekapon.accounts(id) ON DELETE CASCADE,
    theme text NOT NULL DEFAULT 'light' CHECK (theme IN ('light', 'dark')),
    error_duration_minutes smallint NOT NULL DEFAULT 5 CHECK (error_duration_minutes BETWEEN 1 AND 60),
    profile_photo bytea,
    profile_photo_mime text CHECK (profile_photo_mime IS NULL OR profile_photo_mime IN ('image/jpeg', 'image/png', 'image/webp')),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK ((profile_photo IS NULL) = (profile_photo_mime IS NULL)),
    CHECK (profile_photo IS NULL OR octet_length(profile_photo) <= 2097152)
);

CREATE TABLE IF NOT EXISTS ekapon.edit_undo (
    token uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    actor_id bigint NOT NULL REFERENCES ekapon.accounts(id) ON DELETE CASCADE,
    entity_type text NOT NULL CHECK (entity_type IN ('account_profile', 'account', 'dashboard_record')),
    entity_key text NOT NULL,
    before_data jsonb NOT NULL CHECK (jsonb_typeof(before_data) = 'object'),
    after_data jsonb NOT NULL CHECK (jsonb_typeof(after_data) = 'object'),
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL DEFAULT (now() + interval '5 minutes'),
    undone_at timestamptz,
    CHECK (expires_at > created_at)
);

CREATE INDEX IF NOT EXISTS edit_undo_actor_expiry_idx
    ON ekapon.edit_undo (actor_id, expires_at DESC)
    WHERE undone_at IS NULL;

GRANT SELECT, INSERT, UPDATE, DELETE ON ekapon.account_preferences TO ekapon_admin;
GRANT SELECT, INSERT, UPDATE, DELETE ON ekapon.edit_undo TO ekapon_admin;

-- SOURCE: db/007_operations.sql
-- ======================= PART 2 ======================================

DO $$
BEGIN
    IF to_regclass('ekapon.census_submissions') IS NOT NULL THEN
        IF EXISTS (SELECT 1 FROM ekapon.census_submissions) THEN
            RAISE EXCEPTION 'ekapon.census_submissions still contains rows. Export or clear them before running 007.';
        END IF;
        DROP TABLE ekapon.census_submissions;
    END IF;
END
$$;

