-- SOURCE: db/017_census_registry_bridge.sql
-- Stable aliases keep the staff workspace editable without name-based copying.
CREATE TABLE IF NOT EXISTS ekapon.registry_source_links (
 dataset text NOT NULL CHECK(dataset IN ('owners','pets')),
 source_id uuid NOT NULL,record_id text NOT NULL,
 PRIMARY KEY(dataset,source_id),UNIQUE(dataset,record_id)
);
GRANT SELECT,INSERT ON ekapon.registry_source_links TO ekapon_admin;
ALTER TABLE ekapon.census_review_snapshots ADD COLUMN IF NOT EXISTS before_workspace jsonb,ADD COLUMN IF NOT EXISTS after_workspace jsonb;

CREATE OR REPLACE FUNCTION ekapon.publish_registry_owner(p_id uuid) RETURNS void
LANGUAGE plpgsql AS $$
DECLARE o record; target text; p record;
BEGIN
 SELECT r.*,b.name AS barangay FROM ekapon.registry_owners r JOIN ekapon.barangays b ON b.id=r.barangay_id WHERE r.id=p_id INTO o;
 IF NOT FOUND THEN RETURN; END IF;
 INSERT INTO ekapon.registry_source_links(dataset,source_id,record_id) VALUES('owners',p_id,'census-owner:'||p_id) ON CONFLICT DO NOTHING;
 SELECT record_id INTO target FROM ekapon.registry_source_links WHERE dataset='owners' AND source_id=p_id;
 INSERT INTO ekapon.dashboard_records AS d(dataset,record_id,record_data,archived)
 VALUES('owners',target,jsonb_build_object('id',target,'name',o.owner_name,'address',o.address,'contact',coalesce(o.contact,''),'barangay',o.barangay,'barangayId',o.barangay_id,'source',CASE WHEN o.source_submission_id IS NULL THEN 'Staff registry' ELSE 'Approved census' END,'sourceSubmissionId',o.source_submission_id,'_censusSourceId',p_id),o.archived_at IS NOT NULL)
 ON CONFLICT(dataset,record_id) DO UPDATE SET record_data=(d.record_data-'_censusWithdrawn')||excluded.record_data,archived=excluded.archived,updated_at=now();
END $$;
CREATE OR REPLACE FUNCTION ekapon.publish_registry_pet(p_id uuid) RETURNS void
LANGUAGE plpgsql AS $$
DECLARE p record; target text; owner_target text;
BEGIN
 SELECT r.*,o.owner_name,o.barangay_id,b.name AS barangay,o.archived_at AS owner_archived FROM ekapon.registry_pets r JOIN ekapon.registry_owners o ON o.id=r.owner_id JOIN ekapon.barangays b ON b.id=o.barangay_id WHERE r.id=p_id INTO p;
 IF NOT FOUND THEN RETURN; END IF;
 PERFORM ekapon.publish_registry_owner(p.owner_id);
 SELECT record_id INTO owner_target FROM ekapon.registry_source_links WHERE dataset='owners' AND source_id=p.owner_id;
 INSERT INTO ekapon.registry_source_links(dataset,source_id,record_id) VALUES('pets',p_id,'census-pet:'||p_id) ON CONFLICT DO NOTHING;
 SELECT record_id INTO target FROM ekapon.registry_source_links WHERE dataset='pets' AND source_id=p_id;
 INSERT INTO ekapon.dashboard_records AS d(dataset,record_id,record_data,archived)
 VALUES('pets',target,jsonb_build_object('id',target,'petName',p.pet_name,'owner_id',owner_target,'owner',p.owner_name,'barangay',p.barangay,'barangayId',p.barangay_id,'species',p.species,'sex',p.sex,'age_months',p.age_months,'breed_type',p.breed_type,'color',p.color,'sterilized',p.sterilized,'confinement',p.confinement,'vaccine_1st',p.vaccine_1st,'vaccine_2nd',p.vaccine_2nd,'vaccine_3rd',p.vaccine_3rd,'vaccine_other',p.vaccine_other,'booster',p.booster,'laps',p.laps,'registered_year',p.registered_year,'remarks',p.remarks,'_censusSourceId',p_id),p.archived_at IS NOT NULL OR p.owner_archived IS NOT NULL)
 ON CONFLICT(dataset,record_id) DO UPDATE SET record_data=(d.record_data-'_censusWithdrawn')||excluded.record_data,archived=excluded.archived,updated_at=now();
END $$;
CREATE OR REPLACE FUNCTION ekapon.registry_to_workspace() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE kind text; p record;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('registry-owner-pet-writes'));
 kind:=CASE WHEN TG_TABLE_NAME='registry_owners' THEN 'owners' ELSE 'pets' END;
 IF TG_OP='DELETE' THEN
  UPDATE ekapon.dashboard_records d SET archived=true,record_data=record_data||'{"_censusWithdrawn":true}'::jsonb,updated_at=now()
  FROM ekapon.registry_source_links l WHERE l.dataset=kind AND l.source_id=OLD.id AND d.dataset=l.dataset AND d.record_id=l.record_id;
  RETURN OLD;
 END IF;
 IF kind='owners' THEN
  PERFORM ekapon.publish_registry_owner(NEW.id);
  FOR p IN SELECT id FROM ekapon.registry_pets WHERE owner_id=NEW.id LOOP PERFORM ekapon.publish_registry_pet(p.id); END LOOP;
 ELSE PERFORM ekapon.publish_registry_pet(NEW.id); END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS registry_owner_workspace ON ekapon.registry_owners;
CREATE TRIGGER registry_owner_workspace AFTER INSERT OR UPDATE OR DELETE ON ekapon.registry_owners FOR EACH ROW EXECUTE FUNCTION ekapon.registry_to_workspace();
DROP TRIGGER IF EXISTS registry_pet_workspace ON ekapon.registry_pets;
CREATE TRIGGER registry_pet_workspace AFTER INSERT OR UPDATE OR DELETE ON ekapon.registry_pets FOR EACH ROW EXECUTE FUNCTION ekapon.registry_to_workspace();
-- Existing approved census registry records gain aliases; existing staff records remain separate.
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT id FROM ekapon.registry_owners LOOP PERFORM ekapon.publish_registry_owner(r.id); END LOOP;
 FOR r IN SELECT id FROM ekapon.registry_pets LOOP PERFORM ekapon.publish_registry_pet(r.id); END LOOP;
END $$;

-- SOURCE: db/018_census_unknown_fields.sql
ALTER TABLE ekapon.registry_pets ALTER COLUMN sex DROP NOT NULL;
-- Existing false values are preserved. New unknown values can remain unknown.
DO $$ DECLARE tab text; col text; definition text; BEGIN
 FOREACH tab IN ARRAY ARRAY['census_pets','registry_pets'] LOOP
  FOREACH col IN ARRAY ARRAY['sterilized','vaccine_1st','vaccine_2nd','vaccine_3rd','booster','laps'] LOOP
   EXECUTE format('ALTER TABLE ekapon.%I ALTER COLUMN %I DROP NOT NULL, ALTER COLUMN %I DROP DEFAULT',tab,col,col);
  END LOOP;
 END LOOP;
 SELECT pg_get_functiondef('ekapon.decide_census_submission(uuid,text,text)'::regprocedure) INTO definition;
 FOREACH col IN ARRAY ARRAY['sterilized','vaccine_1st','vaccine_2nd','vaccine_3rd','booster','laps'] LOOP
  definition:=replace(definition,col||' = '||col||' OR v_pet.'||col,col||' = CASE WHEN v_pet.'||col||' IS NULL THEN '||col||' WHEN '||col||' IS NULL THEN v_pet.'||col||' ELSE '||col||' OR v_pet.'||col||' END');
 END LOOP;
 EXECUTE definition;
END $$;

-- SOURCE: db/019_census_review_consistency.sql
ALTER TABLE ekapon.census_owners
 ADD COLUMN IF NOT EXISTS decision_reason text CHECK (length(decision_reason) <= 1000),
 ADD COLUMN IF NOT EXISTS match_fingerprint text,
 ADD COLUMN IF NOT EXISTS applied_owner_id uuid;
-- Keep previous decisions even when a pending sheet is corrected and its rows replaced.
CREATE TABLE IF NOT EXISTS ekapon.census_decision_activity (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 submission_id uuid NOT NULL REFERENCES ekapon.census_submissions(id) ON DELETE CASCADE,
 census_owner_id uuid NOT NULL,
 actor_id bigint REFERENCES ekapon.accounts(id) ON DELETE SET NULL,
 actor_name text NOT NULL,
 before_data jsonb NOT NULL, after_data jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS census_decision_activity_submission_idx ON ekapon.census_decision_activity(submission_id,id DESC);
GRANT SELECT,INSERT ON ekapon.census_decision_activity TO ekapon_admin;
GRANT USAGE,SELECT ON SEQUENCE ekapon.census_decision_activity_id_seq TO ekapon_admin;
DO $$ DECLARE definition text; marker text; BEGIN
 SELECT pg_get_functiondef('ekapon.decide_census_submission(uuid,text,text)'::regprocedure) INTO definition;
 IF position('CENSUS_CONFIRMED_MATCH_REQUIRED' in definition)=0 THEN
  marker := '        FOR v_owner IN SELECT * FROM ekapon.census_owners';
  IF position(marker in definition)=0 THEN RAISE EXCEPTION 'Census review function changed; review migration 019.'; END IF;
  definition:=replace(definition,marker,$guard$
        -- CENSUS_CONFIRMED_MATCH_REQUIRED: old pending matches need a fresh staff review.
        IF EXISTS (SELECT 1 FROM ekapon.census_owners WHERE submission_id=p_id
          AND decision IN ('merge','replace','keep')
          AND (matched_owner_id IS NULL OR length(btrim(coalesce(decision_reason,'')))<3 OR match_fingerprint IS NULL)) THEN
          RAISE EXCEPTION 'Compare each selected owner and provide a reason before approval.' USING ERRCODE='22023';
        END IF;
$guard$ || marker);
  marker := '            FOR v_pet IN SELECT * FROM ekapon.census_pets';
  IF position(marker in definition)=0 THEN RAISE EXCEPTION 'Census pet loop changed; review migration 019.'; END IF;
  definition:=replace(definition,marker,'            UPDATE ekapon.census_owners SET applied_owner_id=v_reg_owner WHERE id=v_owner.id;' || E'\n' || marker);
  EXECUTE definition;
 END IF;
END $$;

-- SOURCE: db/020_navigation_badges.sql
-- Compact counters contain no owner/pet payloads. Each bucket's revision is
-- transactional: a late commit changes the fingerprint even after a visit.
CREATE TABLE IF NOT EXISTS ekapon.navigation_changes (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 node_id text NOT NULL,barangay_id integer NOT NULL DEFAULT 0,
 recipient_id bigint NOT NULL DEFAULT 0,actor_id bigint NOT NULL,
 campaign_id bigint NOT NULL DEFAULT 0,revision bigint NOT NULL DEFAULT 1,
 UNIQUE(node_id,barangay_id,recipient_id,actor_id,campaign_id)
);
CREATE INDEX IF NOT EXISTS navigation_changes_node_idx ON ekapon.navigation_changes(node_id,recipient_id,barangay_id);
CREATE TABLE IF NOT EXISTS ekapon.navigation_seen (
 account_id bigint NOT NULL REFERENCES ekapon.accounts(id) ON DELETE CASCADE,
 node_id text NOT NULL,scope_key text NOT NULL,fingerprint text NOT NULL,
 observed_at bigint NOT NULL,PRIMARY KEY(account_id,node_id,scope_key)
);
GRANT SELECT ON ekapon.navigation_changes TO ekapon_admin;
GRANT SELECT,INSERT,UPDATE ON ekapon.navigation_seen TO ekapon_admin;

CREATE OR REPLACE FUNCTION ekapon.touch_navigation(p_node text,p_barangay integer DEFAULT 0,p_recipient bigint DEFAULT 0,p_campaign bigint DEFAULT 0)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ekapon AS $$
DECLARE actor bigint:=nullif(current_setting('app.account_id',true),'')::bigint;
BEGIN
 -- No historical backfill or invented actor: only new changes attributed to staff.
 IF actor IS NULL THEN RETURN; END IF;
 INSERT INTO ekapon.navigation_changes(node_id,barangay_id,recipient_id,actor_id,campaign_id)
 VALUES(p_node,coalesce(p_barangay,0),coalesce(p_recipient,0),actor,coalesce(p_campaign,0))
 ON CONFLICT(node_id,barangay_id,recipient_id,actor_id,campaign_id)
 DO UPDATE SET revision=navigation_changes.revision+1;
END $$;
REVOKE ALL ON FUNCTION ekapon.touch_navigation(text,integer,bigint,bigint) FROM PUBLIC;

CREATE OR REPLACE FUNCTION ekapon.navigation_change_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ekapon AS $$
DECLARE data jsonb; prior jsonb; item jsonb; node text; area integer; campaign bigint; recipient bigint; sub uuid; scope integer; resource jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN prior:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN data:=to_jsonb(NEW); END IF;
 -- Skip timestamp-only touches, login bookkeeping, photos and preferences.
 IF TG_OP='UPDATE' AND (prior-ARRAY['updated_at','last_login_at','failed_attempts','failed_login_count','locked_until','profile_photo','locale','theme'])
   IS NOT DISTINCT FROM (data-ARRAY['updated_at','last_login_at','failed_attempts','failed_login_count','locked_until','profile_photo','locale','theme']) THEN RETURN NULL; END IF;
 FOR item IN SELECT DISTINCT value FROM jsonb_array_elements(jsonb_build_array(prior,data)) WHERE value<>'null'::jsonb LOOP
  area:=coalesce((item->>'barangay_id')::integer,0);campaign:=0;recipient:=0;
  IF TG_TABLE_NAME='dashboard_records' THEN
   resource:=item->'record_data';IF coalesce((resource->>'_sampleData')::boolean,false) THEN CONTINUE; END IF;
   area:=coalesce(ekapon.find_barangay(resource->>'barangay'),0);
   node:=CASE item->>'dataset' WHEN 'owners' THEN 'owners' WHEN 'pets' THEN 'pets' WHEN 'respondents' THEN 'respondents' WHEN 'participants' THEN 'participants' WHEN 'paravets' THEN 'paravets' WHEN 'services' THEN 'services' WHEN 'stubs' THEN 'stubs' WHEN 'programs' THEN 'programs' END;
   IF node='programs' THEN SELECT c.id INTO campaign FROM ekapon.program_interest_campaigns c WHERE c.program_record_id=(item->>'id')::bigint; END IF;
   IF node IS NOT NULL THEN PERFORM ekapon.touch_navigation(node,area,0,coalesce(campaign,0)); END IF;
   IF node='programs' THEN PERFORM ekapon.touch_navigation('program-day',area,0,coalesce(campaign,0)); END IF;
   IF node IN ('owners','pets') THEN PERFORM ekapon.touch_navigation('quality',area); END IF;
   IF node IN ('owners','pets','participants','respondents','services','programs') THEN PERFORM ekapon.touch_navigation('reports',area); END IF;
  ELSIF TG_TABLE_NAME IN ('census_submissions','census_owners','census_pets') THEN
   IF TG_TABLE_NAME='census_submissions' THEN resource:=item;
   ELSE
    IF TG_TABLE_NAME='census_owners' THEN sub:=(item->>'submission_id')::uuid;
    ELSE SELECT o.submission_id INTO sub FROM ekapon.census_owners o WHERE o.id=(item->>'owner_id')::uuid; END IF;
    SELECT to_jsonb(s) INTO resource FROM ekapon.census_submissions s WHERE s.id=sub;
   END IF;
   IF resource IS NOT NULL THEN
    PERFORM ekapon.touch_navigation('census-'||(resource->>'status'),coalesce((resource->>'barangay_id')::integer,0));
    PERFORM ekapon.touch_navigation('census-mine',0,(resource->>'submitted_by')::bigint);
   END IF;
  ELSIF TG_TABLE_NAME IN ('program_interest_campaigns','program_interest_allowed_barangays','program_interest_people','stub_batches','stub_tickets','program_attendance','program_runtime') THEN
   IF TG_TABLE_NAME='program_interest_campaigns' THEN campaign:=(item->>'id')::bigint;
   ELSIF TG_TABLE_NAME='program_runtime' THEN SELECT c.id INTO campaign FROM ekapon.program_interest_campaigns c WHERE c.program_record_id=(item->>'program_record_id')::bigint;
   ELSIF TG_TABLE_NAME='stub_tickets' THEN SELECT b.campaign_id,b.barangay_id,b.recipient_id INTO campaign,area,recipient FROM ekapon.stub_batches b WHERE b.id=(item->>'batch_id')::bigint;
   ELSE campaign:=(item->>'campaign_id')::bigint; END IF;
   SELECT c.host_barangay_id INTO scope FROM ekapon.program_interest_campaigns c WHERE c.id=campaign;
   IF TG_TABLE_NAME IN ('stub_batches','stub_tickets') THEN
    IF TG_TABLE_NAME='stub_batches' THEN recipient:=(item->>'recipient_id')::bigint; END IF;
    PERFORM ekapon.touch_navigation('stubs',area,recipient,campaign);
   ELSIF TG_TABLE_NAME='program_attendance' THEN PERFORM ekapon.touch_navigation('reports',(item->>'owner_barangay_id')::integer,0,campaign);
    PERFORM ekapon.touch_navigation('participants',(item->>'owner_barangay_id')::integer,0,campaign);
   ELSE
    IF TG_TABLE_NAME='program_interest_people' THEN area:=(item->>'residence_barangay_id')::integer; ELSE area:=0; END IF;
    PERFORM ekapon.touch_navigation('program-interest',area,0,campaign);
   END IF;
   PERFORM ekapon.touch_navigation('programs',coalesce(scope,0),0,campaign);
   PERFORM ekapon.touch_navigation('program-day',coalesce(scope,0),0,campaign);
  ELSIF TG_TABLE_NAME='data_quality_reviews' THEN
   SELECT coalesce(ekapon.find_barangay(d.record_data->>'barangay'),0) INTO area FROM ekapon.dashboard_records d WHERE d.id=(item->>'left_record_id')::bigint;
   PERFORM ekapon.touch_navigation('quality',area);
  ELSIF TG_TABLE_NAME='permission_requests' THEN
   PERFORM ekapon.touch_navigation('access');PERFORM ekapon.touch_navigation('access-request',0,(item->>'requester_id')::bigint);
  ELSIF TG_TABLE_NAME='access_grants' THEN PERFORM ekapon.touch_navigation('access');
  ELSIF TG_TABLE_NAME='issue_reports' THEN PERFORM ekapon.touch_navigation('issues');
  ELSIF TG_TABLE_NAME='accounts' THEN
   IF item->>'account_type' IN ('Admin','Paravet') THEN PERFORM ekapon.touch_navigation('accounts'); END IF;
  ELSIF TG_TABLE_NAME='barangays' THEN PERFORM ekapon.touch_navigation('barangays');
  ELSIF TG_TABLE_NAME='registry_owners' THEN
   PERFORM ekapon.touch_navigation('census-summary',area);PERFORM ekapon.touch_navigation('census-front',area);
  ELSIF TG_TABLE_NAME='registry_pets' THEN
   SELECT o.barangay_id INTO area FROM ekapon.registry_owners o WHERE o.id=(item->>'owner_id')::uuid;
   PERFORM ekapon.touch_navigation('census-summary',area);PERFORM ekapon.touch_navigation('census-front',area);
  END IF;
 END LOOP;
 RETURN NULL;
END $$;
DO $$ DECLARE tab text; BEGIN
 FOREACH tab IN ARRAY ARRAY['dashboard_records','census_submissions','census_owners','census_pets','program_interest_campaigns','program_interest_allowed_barangays','program_interest_people','stub_batches','stub_tickets','program_attendance','program_runtime','data_quality_reviews','permission_requests','access_grants','issue_reports','accounts','barangays','registry_owners','registry_pets'] LOOP
  EXECUTE format('DROP TRIGGER IF EXISTS navigation_changed ON ekapon.%I',tab);
  EXECUTE format('CREATE TRIGGER navigation_changed AFTER INSERT OR UPDATE OR DELETE ON ekapon.%I FOR EACH ROW EXECUTE FUNCTION ekapon.navigation_change_trigger()',tab);
 END LOOP;
END $$;
CREATE INDEX IF NOT EXISTS census_pending_badge_idx ON ekapon.census_submissions(status) WHERE status='pending';

-- SOURCE: db/021_field_record_consistency.sql
-- Confirmed snapshots survive later registry changes. Images are never part of this workflow.
CREATE TABLE IF NOT EXISTS ekapon.standalone_services (
 id uuid PRIMARY KEY,
 actor_id bigint NOT NULL REFERENCES ekapon.accounts(id) ON DELETE RESTRICT,
 payload_hash text NOT NULL,
 owner_record_id text NOT NULL,
 owner_snapshot jsonb NOT NULL CHECK (jsonb_typeof(owner_snapshot)='object'),
 pets_snapshot jsonb NOT NULL CHECK (jsonb_typeof(pets_snapshot)='array' AND jsonb_array_length(pets_snapshot) BETWEEN 1 AND 30),
 served_on date NOT NULL,
 location text NOT NULL CHECK(length(btrim(location)) BETWEEN 1 AND 300),
 provider text NOT NULL CHECK(length(btrim(provider)) BETWEEN 1 AND 120),
 note text NOT NULL DEFAULT '',duplicate_reason text,
 status text NOT NULL DEFAULT 'Submitted' CHECK(status IN ('Submitted','Voided')),
 created_at timestamptz NOT NULL DEFAULT now(),
 voided_by bigint REFERENCES ekapon.accounts(id) ON DELETE RESTRICT,
 voided_at timestamptz,void_reason text,
 CHECK ((status='Submitted' AND voided_by IS NULL AND voided_at IS NULL AND void_reason IS NULL)
   OR (status='Voided' AND voided_by IS NOT NULL AND voided_at IS NOT NULL AND length(btrim(void_reason))>=3))
);
CREATE INDEX IF NOT EXISTS standalone_services_owner_date_idx ON ekapon.standalone_services(owner_record_id,served_on) WHERE status='Submitted';
CREATE INDEX IF NOT EXISTS standalone_services_date_idx ON ekapon.standalone_services(served_on DESC,id);
GRANT SELECT,INSERT,UPDATE ON ekapon.standalone_services TO ekapon_admin;

CREATE OR REPLACE FUNCTION ekapon.field_record_navigation_trigger() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ekapon AS $$
DECLARE item jsonb; area integer;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements(CASE WHEN TG_OP='INSERT' THEN jsonb_build_array(to_jsonb(NEW)) WHEN TG_OP='DELETE' THEN jsonb_build_array(to_jsonb(OLD)) ELSE jsonb_build_array(to_jsonb(OLD),to_jsonb(NEW)) END) LOOP
  IF TG_TABLE_NAME='standalone_services' THEN
   area:=coalesce(ekapon.find_barangay(item->'owner_snapshot'->>'barangay'),0);
   PERFORM ekapon.touch_navigation('services',area);PERFORM ekapon.touch_navigation('reports',area);
  ELSIF item->>'status'='approved' THEN
   PERFORM ekapon.touch_navigation('respondents',(item->>'barangay_id')::integer);
  END IF;
 END LOOP;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS field_record_navigation ON ekapon.standalone_services;
CREATE TRIGGER field_record_navigation AFTER INSERT OR UPDATE OR DELETE ON ekapon.standalone_services FOR EACH ROW EXECUTE FUNCTION ekapon.field_record_navigation_trigger();
DROP TRIGGER IF EXISTS field_record_navigation ON ekapon.census_submissions;
CREATE TRIGGER field_record_navigation AFTER INSERT OR UPDATE OR DELETE ON ekapon.census_submissions FOR EACH ROW EXECUTE FUNCTION ekapon.field_record_navigation_trigger();

-- SOURCE: db/022_daily_read_indexes.sql
-- Prepared for local disposable validation only. No data or identity changes.
-- These orderings match bounded Recent updates and the default registry list.

CREATE INDEX IF NOT EXISTS dashboard_registry_recent_order_idx
  ON ekapon.dashboard_records(dataset,updated_at DESC,record_id)
