-- SOURCE: db/023_workflow_redesign.sql
ALTER TABLE ekapon.program_interest_campaigns DROP CONSTRAINT IF EXISTS program_interest_campaigns_status_check;
ALTER TABLE ekapon.program_interest_campaigns ADD CONSTRAINT program_interest_campaigns_status_check CHECK(status IN ('gathering','requested','approved','rejected','scheduled','closed','cancelled'));
ALTER TABLE ekapon.program_interest_campaigns ADD COLUMN IF NOT EXISTS revision integer NOT NULL DEFAULT 1;
ALTER TABLE ekapon.program_interest_activity DROP CONSTRAINT IF EXISTS program_interest_activity_action_check;
ALTER TABLE ekapon.program_interest_activity ADD CONSTRAINT program_interest_activity_action_check CHECK(action IN ('created','interest-added','interest-updated','interest-withdrawn','request-submitted','request-approved','request-rejected','program-scheduled','program-access-updated','closed','reopened','request-edited','request-cancelled'));
-- Existing duplicate requests remain visible for explicit resolution. New writes
-- are serialized per barangay even when old installations contain duplicates.
CREATE OR REPLACE FUNCTION ekapon.enforce_active_demand() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.campaign_type='program_request' AND NEW.status IN ('gathering','requested','approved','scheduled') THEN
  PERFORM pg_advisory_xact_lock(73023,NEW.host_barangay_id);
  IF EXISTS(SELECT 1 FROM ekapon.program_interest_campaigns c WHERE c.host_barangay_id=NEW.host_barangay_id AND c.campaign_type='program_request' AND c.status IN ('gathering','requested','approved','scheduled') AND c.id<>NEW.id) THEN
   RAISE EXCEPTION 'An active request already exists for this barangay' USING ERRCODE='23505';
  END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS active_demand_guard ON ekapon.program_interest_campaigns;
CREATE TRIGGER active_demand_guard BEFORE INSERT OR UPDATE OF status,host_barangay_id ON ekapon.program_interest_campaigns FOR EACH ROW EXECUTE FUNCTION ekapon.enforce_active_demand();
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM ekapon.program_interest_campaigns WHERE campaign_type='program_request' AND status IN ('gathering','requested','approved','scheduled') GROUP BY host_barangay_id HAVING count(*)>1) THEN
  CREATE UNIQUE INDEX IF NOT EXISTS one_active_barangay_demand ON ekapon.program_interest_campaigns(host_barangay_id) WHERE campaign_type='program_request' AND status IN ('gathering','requested','approved','scheduled');
 END IF;
END $$;
ALTER TABLE ekapon.registry_activity DROP CONSTRAINT IF EXISTS registry_activity_action_check;
ALTER TABLE ekapon.registry_activity ADD CONSTRAINT registry_activity_action_check CHECK(action IN ('owner-created','pet-created','owner-updated','pet-updated','owner-link-corrected','owner-details-synced','interest-linked','stub-linked','attendance-linked','pets-linked','pets-unlinked'));
ALTER TABLE ekapon.program_interest_people ADD COLUMN IF NOT EXISTS registry_owner_id text;
CREATE TABLE IF NOT EXISTS ekapon.report_drafts (
 id uuid PRIMARY KEY,account_id bigint NOT NULL REFERENCES ekapon.accounts(id) ON DELETE RESTRICT,
 title text NOT NULL CHECK(length(title) BETWEEN 1 AND 160),content jsonb NOT NULL,
 version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS report_drafts_account_idx ON ekapon.report_drafts(account_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS ekapon.policy_acceptances (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,account_id bigint NOT NULL REFERENCES ekapon.accounts(id) ON DELETE RESTRICT,
 policy_version text NOT NULL,language text NOT NULL CHECK(language IN ('en','fil')),accepted_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS ekapon.pet_breed_references (
 species text NOT NULL CHECK(species IN ('Dog','Cat')),name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 100),
 active boolean NOT NULL DEFAULT true,PRIMARY KEY(species,name)
);
CREATE TABLE IF NOT EXISTS ekapon.registry_intake_links (
 source text NOT NULL CHECK(source IN ('interest','stub','attendance')),source_id bigint NOT NULL,
 owner_record_id text NOT NULL,actor_id bigint NOT NULL REFERENCES ekapon.accounts(id) ON DELETE RESTRICT,
 created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(source,source_id)
);
GRANT SELECT,INSERT ON ekapon.registry_intake_links TO ekapon_admin;
ALTER TABLE ekapon.stub_batches ADD COLUMN IF NOT EXISTS external_pdf bytea;
ALTER TABLE ekapon.stub_batches ADD COLUMN IF NOT EXISTS external_pdf_name text;
ALTER TABLE ekapon.dashboard_import_batches ADD COLUMN IF NOT EXISTS linked_batch_id uuid;
ALTER TABLE ekapon.census_pets DROP CONSTRAINT IF EXISTS census_pets_breed_type_check;
ALTER TABLE ekapon.census_pets ADD CONSTRAINT census_pets_breed_type_check CHECK(breed_type IS NULL OR breed_type IN ('Mongrel','Mix','Pure'));
ALTER TABLE ekapon.registry_pets DROP CONSTRAINT IF EXISTS registry_pets_breed_type_check;
ALTER TABLE ekapon.registry_pets ADD CONSTRAINT registry_pets_breed_type_check CHECK(breed_type IS NULL OR breed_type IN ('Mongrel','Mix','Pure'));
CREATE OR REPLACE FUNCTION ekapon.sync_paravet_directory() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.account_type::text='Paravet' THEN
  UPDATE ekapon.dashboard_records SET record_data=record_data||jsonb_build_object('name',NEW.full_name,'firstName',NEW.first_name,'middleName',coalesce(NEW.middle_name,''),'lastName',NEW.last_name,'suffix',coalesce(NEW.suffix,''),'mobile',coalesce(NEW.mobile,''),'barangay',coalesce((SELECT name FROM ekapon.barangays WHERE id=NEW.barangay_id),'')),archived=NEW.archived_at IS NOT NULL,updated_at=now() WHERE dataset='paravets' AND record_data->>'accountId'=NEW.id::text;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS paravet_directory_assignment ON ekapon.accounts;
CREATE TRIGGER paravet_directory_assignment AFTER UPDATE OF first_name,middle_name,last_name,suffix,mobile,barangay_id,archived_at ON ekapon.accounts FOR EACH ROW EXECUTE FUNCTION ekapon.sync_paravet_directory();
CREATE OR REPLACE FUNCTION ekapon.workflow_notice(p_campaign bigint,p_barangay integer,p_title text,p_body text,p_link text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ekapon AS $$
DECLARE actor ekapon.accounts;
BEGIN
 actor:=ekapon.actor_account(ARRAY['SuperAdmin','Admin','Paravet']);
 IF actor.account_type::text='Paravet' AND (p_barangay IS NULL OR p_barangay<>actor.barangay_id OR NOT EXISTS(SELECT 1 FROM ekapon.program_interest_campaigns c WHERE c.id=p_campaign AND (c.host_barangay_id=actor.barangay_id OR EXISTS(SELECT 1 FROM ekapon.program_interest_allowed_barangays a WHERE a.campaign_id=c.id AND a.barangay_id=actor.barangay_id)))) THEN RAISE EXCEPTION 'Notice outside assigned area' USING ERRCODE='42501'; END IF;
 INSERT INTO ekapon.notifications(recipient_id,kind,title,body,link)
 SELECT id,'program',left(p_title,160),left(p_body,1000),left(p_link,300) FROM ekapon.accounts WHERE status='Active' AND archived_at IS NULL AND ((p_barangay IS NULL AND account_type::text IN ('Admin','SuperAdmin')) OR (p_barangay IS NOT NULL AND account_type::text='Paravet' AND barangay_id=p_barangay));
END $$;
REVOKE ALL ON FUNCTION ekapon.workflow_notice(bigint,integer,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ekapon.workflow_notice(bigint,integer,text,text,text) TO ekapon_admin;
GRANT SELECT,INSERT,UPDATE,DELETE ON ekapon.report_drafts TO ekapon_admin;
GRANT SELECT,INSERT ON ekapon.policy_acceptances TO ekapon_admin;
GRANT USAGE,SELECT ON SEQUENCE ekapon.policy_acceptances_id_seq TO ekapon_admin;
GRANT SELECT,INSERT,UPDATE ON ekapon.pet_breed_references TO ekapon_admin;

-- SOURCE: db/024_private_file_storage.sql
