-- SOURCE: db/027_salin_stubs.sql
-- 027: stubs that paravets print in Salin, and that follow owner edits.
-- * Admin can send an approved batch to its barangay: Salin then lists it for
--   the paravets there to print. Status is unchanged (Approved until printed).
-- * When a paravet edits an owner in a program request, that owner's issued
--   stub is updated too; details_updated_at marks slips worth reprinting.
-- * The owner writes their name on the printed (blank-name) stub; the paravet
--   encodes it in Salin, and owner_confirmed_at records that.
-- Additive and idempotent: safe to run twice. Apply after 026.

ALTER TABLE ekapon.stub_batches ADD COLUMN IF NOT EXISTS sent_by bigint REFERENCES ekapon.accounts(id) ON DELETE RESTRICT;
ALTER TABLE ekapon.stub_batches ADD COLUMN IF NOT EXISTS sent_at timestamptz;
ALTER TABLE ekapon.stub_tickets ADD COLUMN IF NOT EXISTS details_updated_at timestamptz;
ALTER TABLE ekapon.stub_tickets ADD COLUMN IF NOT EXISTS owner_confirmed_at timestamptz;
ALTER TABLE ekapon.stub_activity DROP CONSTRAINT IF EXISTS stub_activity_action_check;
ALTER TABLE ekapon.stub_activity ADD CONSTRAINT stub_activity_action_check CHECK (action IN ('batch-requested','batch-approved','batch-rejected','batch-printed','batch-reprinted','batch-handed-over','stub-issued','manual-issue-recorded','stub-cancelled','stub-redeemed','walk-in-submitted','attendance-voided','batch-sent','stub-details-updated','owner-confirmed'));
CREATE INDEX IF NOT EXISTS stub_tickets_interest_person_idx ON ekapon.stub_tickets(interest_person_id) WHERE interest_person_id IS NOT NULL;

-- Rollback: BEGIN; DROP INDEX IF EXISTS ekapon.stub_tickets_interest_person_idx;
--   ALTER TABLE ekapon.stub_tickets DROP COLUMN IF EXISTS details_updated_at, DROP COLUMN IF EXISTS owner_confirmed_at;
--   ALTER TABLE ekapon.stub_batches DROP COLUMN IF EXISTS sent_at, DROP COLUMN IF EXISTS sent_by;
--   (after deleting any 'batch-sent'/'stub-details-updated'/'owner-confirmed' activity rows) restore the 012 action list on stub_activity_action_check; COMMIT;

-- SOURCE: db/028_superadmin_only.sql
-- 028: City Vet keeps one staff role. Every Admin account becomes a SuperAdmin;
-- existing SuperAdmins are unchanged. Account creation already offers Paravet
-- only, so no new Admin accounts are made. The 'Admin' enum value stays for old
-- audit rows and is simply no longer used.
-- Not in the local test schema (scripts/local-schema.mjs): the tests still sign in
-- as the seeded Admin to cover the old role checks.
-- Idempotent: safe to run twice. Apply after 027.

UPDATE ekapon.accounts SET account_type = 'SuperAdmin' WHERE account_type = 'Admin';

-- Rollback: not automatic. Before running, note the Admin accounts with
--   SELECT id, username FROM ekapon.accounts WHERE account_type = 'Admin';
-- and set those ids back to 'Admin' if needed.

-- SOURCE: db/029_census_request_id.sql
-- 029: Salin sends census submissions from its outbox and may resend one after
-- a dropped connection; request_id makes the resend return the first
-- submission instead of creating a duplicate.
-- Additive and idempotent: safe to run twice. Apply after 028.

ALTER TABLE ekapon.census_submissions ADD COLUMN IF NOT EXISTS request_id uuid;
CREATE UNIQUE INDEX IF NOT EXISTS census_submissions_request_uq ON ekapon.census_submissions(request_id) WHERE request_id IS NOT NULL;

-- Rollback:
--   BEGIN; DROP INDEX IF EXISTS ekapon.census_submissions_request_uq; ALTER TABLE ekapon.census_submissions DROP COLUMN IF EXISTS request_id; COMMIT;

-- SOURCE: db/030_password_reset_email.sql
-- 030: Paravets reset a forgotten password with a code sent to their email.
-- * accounts.email is the paravet's own address, saved only after they confirm a
--   code sent to it (email_verified_at), so codes never go to a mistyped address.
-- * email_codes holds the 6-digit codes (hashed, 10 minutes, 5 tries) for
--   confirming an email and for resetting a password.
-- * sessions_valid_after: a reset signs the account out everywhere else
--   (sessions issued before it stop working).
-- Additive and idempotent: safe to run twice. Apply after 029.

ALTER TABLE ekapon.accounts ADD COLUMN IF NOT EXISTS email text CHECK (email IS NULL OR length(email) <= 254);
ALTER TABLE ekapon.accounts ADD COLUMN IF NOT EXISTS email_verified_at timestamptz;
ALTER TABLE ekapon.accounts ADD COLUMN IF NOT EXISTS sessions_valid_after timestamptz;
CREATE UNIQUE INDEX IF NOT EXISTS accounts_email_uq ON ekapon.accounts(lower(email)) WHERE email IS NOT NULL;
GRANT SELECT (email, email_verified_at, sessions_valid_after) ON ekapon.accounts TO ekapon_admin;
GRANT UPDATE (email, email_verified_at, sessions_valid_after) ON ekapon.accounts TO ekapon_admin;
CREATE TABLE IF NOT EXISTS ekapon.email_codes (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id bigint NOT NULL REFERENCES ekapon.accounts(id) ON DELETE CASCADE,
  purpose text NOT NULL CHECK (purpose IN ('verify-email', 'reset-password')),
  email text NOT NULL CHECK (length(email) <= 254),
  code_hash text NOT NULL,
  attempts integer NOT NULL DEFAULT 0,
  expires_at timestamptz NOT NULL,
  used_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS email_codes_account_idx ON ekapon.email_codes(account_id, purpose, created_at DESC);
GRANT SELECT, INSERT, UPDATE ON ekapon.email_codes TO ekapon_admin;
GRANT USAGE, SELECT ON SEQUENCE ekapon.email_codes_id_seq TO ekapon_admin;

-- Rollback:
--   BEGIN; DROP TABLE IF EXISTS ekapon.email_codes; DROP INDEX IF EXISTS ekapon.accounts_email_uq;
--   ALTER TABLE ekapon.accounts DROP COLUMN IF EXISTS sessions_valid_after, DROP COLUMN IF EXISTS email_verified_at, DROP COLUMN IF EXISTS email; COMMIT;

-- SOURCE: db/031_email_codes_no_rls.sql
-- 031: Supabase turns on row-level security for newly created tables, which
-- blocked every insert into ekapon.email_codes (from 030) for the API role.
-- e-Kapon does not use RLS: the API checks every account and scope itself,
-- like for all other ekapon tables. Turn it off for email_codes.
-- Idempotent: safe to run twice. Apply after 030.

ALTER TABLE ekapon.email_codes DISABLE ROW LEVEL SECURITY;

-- Rollback: ALTER TABLE ekapon.email_codes ENABLE ROW LEVEL SECURITY; (password reset by email stops working)

-- No database password is embedded. Enable the API login separately in the SQL Editor.
CREATE ROLE ekapon_api NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
GRANT ekapon_admin TO ekapon_api;
GRANT USAGE ON SCHEMA extensions TO ekapon_api;
REVOKE CREATE ON SCHEMA public FROM ekapon_api;
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA ekapon FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA ekapon REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
DO $$ DECLARE api_role text; BEGIN
  FOREACH api_role IN ARRAY ARRAY['anon','authenticated'] LOOP
    IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=api_role) THEN
      EXECUTE format('REVOKE ALL ON SCHEMA ekapon FROM %I',api_role);
      EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA ekapon FROM %I',api_role);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA ekapon FROM %I',api_role);
      EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA ekapon FROM %I',api_role);
    END IF;
  END LOOP;
END $$;
CREATE TABLE ekapon.schema_migrations(file text PRIMARY KEY,sha256 text NOT NULL,applied_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON ekapon.schema_migrations FROM PUBLIC;
GRANT SELECT ON ekapon.schema_migrations TO ekapon_admin;
